"css": "\n.ys-qa-q { list-style: none; cursor: pointer; transition: color 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-qa-q::-webkit-details-marker { display: none; }\n.ys-qa-q::marker { content: \"\"; }\n.ys-qa-q:hover { color: var(--d9039d0b-819d-46c0-955a-c724d9bf8417); }\n.ys-qa-q:focus-visible { outline: 3px solid var(--d9039d0b-819d-46c0-955a-c724d9bf8417); outline-offset: 2px; }\n.ys-qa-t { transition: transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ys-qa-q:active .ys-qa-t { transform: translateY(1px); }\n.ys-qa[open] .ys-pm-v { display: none; }\n@media (prefers-reduced-motion: reduce) { .ys-qa-q, .ys-qa-t { transition: none; } }\n",
"js": "\nconst live = typeof window !== \"undefined\";\nconst items = Array.from(this.querySelectorAll(\".ys-qa\"));\nconst heads = items.map((item) => item.querySelector(\".ys-qa-q\"));\n// the canvas hands booleans over as strings\nconst truthy = (value) => value === true || value === \"true\" || value === 1 || value === \"1\";\nconst single = truthy(props.single_open);\nitems.forEach((item, i) => { item.open = !truthy(props.all_closed) && i === 0; });\nif (!live) return;\nconst cleanups = [];\nconst on = (el, type, fn) => { if (!el) return; el.addEventListener(type, fn); cleanups.push(() => el.removeEventListener(type, fn)); };\nitems.forEach((item, i) => {\n  on(item, \"toggle\", () => {\n    if (single && item.open) items.forEach((other) => { if (other !== item) other.open = false; });\n  });\n  on(heads[i], \"keydown\", (event) => {\n    const moves = { ArrowDown: 1, ArrowUp: -1 };\n    let next = null;\n    if (event.key in moves) next = (i + moves[event.key] + heads.length) % heads.length;\n    else if (event.key === \"Home\") next = 0;\n    else if (event.key === \"End\") next = heads.length - 1;\n    if (next === null) return;\n    event.preventDefault();\n    heads[next].focus();\n  });\n});\nreturn () => cleanups.forEach((fn) => fn());\n"
